import { Injectable, signal } from '@angular/core';
import type { Book } from './book.model';
import type { BookFormModel } from './book.schema';
import { EXAMPLE_BOOKS } from './book-example-data';

@Injectable({ providedIn: 'root' })
export class BookService {
  private readonly _books = signal<Book[]>(EXAMPLE_BOOKS);
  private readonly _nextId = signal(
    Math.max(0, ...EXAMPLE_BOOKS.map((item) => parseInt(item.id, 10))) + 1,
  );

  readonly books = this._books.asReadonly();

  byId(id: string): Book | undefined {
    return this._books().find((item) => item.id === id);
  }

  create(candidate: BookFormModel): Book {
    const book: Book = {
      id: String(this._nextId()),
      availability: 'Available',
      condition: 'Good',
      timesLoaned: 0,
      onTimeRate: 0,
      holdsPlaced: 0,
      ...candidate,
    };
    this._books.update((items) => [...items, book]);
    this._nextId.update((n) => n + 1);
    return book;
  }

  update(id: string, patch: Partial<BookFormModel>): void {
    this._books.update((items) =>
      items.map((item) => (item.id === id ? { ...item, ...patch } : item)),
    );
  }

  remove(id: string): void {
    this._books.update((items) => items.filter((item) => item.id !== id));
  }
}
